{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Acamprosate, a small polar zwitterion with an acidic sulfonate, has absolute oral bioavailability of only 11 ± 1% in humans; the query is larger and contains two free carboxylic acids plus multiple amides, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Octreotide, a cyclic peptide, has absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers; cyclic peptide-like scaffolds with multiple polar groups show very low oral F, supporting low for the query's diketopiperazine peptide-like structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Colistin, a cyclic peptide, has low and virtually negligible oral bioavailability in patients; this supports low F for the query, which is also a peptide-like macrocycle with multiple polar and ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Microcystin-LR, a cyclic peptide with multiple carboxylate groups, is reported to have low oral bioavailability in humans; the query similarly contains two free carboxylic acids and an amide-rich structure, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "MMF has 90–95% oral bioavailability, but as a small lipophilic monomethyl ester prodrug; this high-F evidence is not transferable to the query's large, multiply charged peptide-like structure and is contradictory only in direction, not in weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar, peptide-like diketopiperazine bearing two free carboxylic acids and multiple amide groups. The most relevant experimental evidence from polar/cyclic peptide drugs (acamprosate, octreotide, colistin, microcystin) consistently shows low or very low oral bioavailability. High-F small-molecule analogues such as MMF rely on small size, ester prodrug character, or specific transporters and do not transfer to this scaffold. Therefore the query is predicted to have low oral bioavailability (F < 20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query or a close analogue with high Morgan similarity.",
    "All retrieved evidence molecules have low structural similarity (<0.3), so transferability is limited.",
    "No data are available on possible active transport, efflux, or prodrug behavior for this specific diketopiperazine scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

